import struct,zlib
from collections import Counter

def rgba_pixels(path):
    b=open(path,'rb').read(); pos=8; dat=b''
    while pos<len(b):
        n=struct.unpack('>I',b[pos:pos+4])[0]; typ=b[pos+4:pos+8]; d=b[pos+8:pos+8+n]; pos+=12+n
        if typ==b'IHDR': w,h,depth,color,_,_,_=struct.unpack('>IIBBBBB',d); assert (depth,color)==(8,6)
        elif typ==b'IDAT': dat+=d
    raw=zlib.decompress(dat); stride=w*4; rows=[]; prev=bytearray(stride); off=0
    for y in range(h):
        f=raw[off]; off+=1; cur=bytearray(raw[off:off+stride]); off+=stride
        for x in range(stride):
            a=cur[x-4] if x>=4 else 0; b0=prev[x]; c=prev[x-4] if x>=4 else 0
            if f==1: cur[x]=(cur[x]+a)&255
            elif f==2: cur[x]=(cur[x]+b0)&255
            elif f==3: cur[x]=(cur[x]+((a+b0)//2))&255
            elif f==4:
                p=a+b0-c; pa=abs(p-a); pb=abs(p-b0); pc=abs(p-c); cur[x]=(cur[x]+(a if pa<=pb and pa<=pc else b0 if pb<=pc else c))&255
            elif f!=0: raise ValueError(f)
        rows.append(cur); prev=cur
    return w,h,rows
for p in ['/tmp/04A-campo-operacion.png','/tmp/04B-flujo-continuo.png','/tmp/04C-intencion-estructurada.png']:
    w,h,rows=rgba_pixels(p); bg=tuple(rows[0][0:4]); xs=[]; ys=[]; non=0
    for y,row in enumerate(rows):
        for x in range(w):
            if tuple(row[x*4:x*4+4]) != bg: xs.append(x); ys.append(y); non+=1
    print(p, 'size', (w,h), 'top-left', bg, 'non-bg-bbox', (min(xs),min(ys),max(xs)+1,max(ys)+1), 'non-bg-pixels',non)
